corpus_block("test-position-stack.R: can request reverse stacking", {
  df <- data_frame(
      y = c(-2, 2, -1, 1),
      g = c("a", "a", "b", "b")
    )
  .plot("test-position-stack.R: can request reverse stacking #1", p <- ggplot(df, aes(1, y, fill = g)) +
      geom_col(position = position_stack(reverse = TRUE)))
  dat <- get_layer_data(p)
})

corpus_block("test-position-stack.R: data with no extent is stacked correctly", {
  df <- data_frame(
      x = c(1, 1),
      y = c(-40, -75),
      group = letters[1:2]
    )
  .plot("test-position-stack.R: data with no extent is stacked correctly #1", base <- ggplot(df, aes(x, y, group = group, label = y)))
  .plot("test-position-stack.R: data with no extent is stacked correctly #2", p0 <- base + geom_text(position = position_stack(vjust = 0)))
  .plot("test-position-stack.R: data with no extent is stacked correctly #3", p1 <- base + geom_text(position = position_stack(vjust = 1)))
  .plot("test-position-stack.R: data with no extent is stacked correctly #4", p2 <- base + geom_text(aes(group = 1L), position = position_stack(vjust = 0.5)))
})

